#' Multifocal / Primary-Metastasis Concordance
#'
#' Assesses concordance of biomarkers or mutations across multiple foci of a 
#' tumour, or between paired primary and metastasis samples. Reports 
#' per-marker concordance rates, Cohen's kappa for paired (two-sample) 
#' designs, and a case-level clonality summary.
#' 
#' @param data .
#' @param caseId Identifier grouping the foci / samples that belong to the
#'   same patient.
#' @param focusId Identifier of the focus or sample within a case (e.g.
#'   primary vs metastasis, or focus 1/2/3). Used to order paired comparisons.
#' @param markers One or more categorical biomarker / mutation status
#'   variables to assess.
#' @param showPerMarker .
#' @param showKappa .
#' @param showCaseLevel .
#' @param showDiscordance .
#' @param showPlot .
#' @param showSummary .
#' @param showExplanation .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$perMarkerTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$caseLevelTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$discordanceTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$explanation} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$perMarkerTable$asDF}
#'
#' \code{as.data.frame(results$perMarkerTable)}
#'
#' @export
multifocalconcordance <- function(
    data,
    caseId,
    focusId,
    markers,
    showPerMarker = TRUE,
    showKappa = TRUE,
    showCaseLevel = TRUE,
    showDiscordance = FALSE,
    showPlot = TRUE,
    showSummary = TRUE,
    showExplanation = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("multifocalconcordance requires jmvcore to be installed (restart may be required)")

    if ( ! missing(caseId)) caseId <- jmvcore::resolveQuo(jmvcore::enquo(caseId))
    if ( ! missing(focusId)) focusId <- jmvcore::resolveQuo(jmvcore::enquo(focusId))
    if ( ! missing(markers)) markers <- jmvcore::resolveQuo(jmvcore::enquo(markers))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(caseId), caseId, NULL),
            `if`( ! missing(focusId), focusId, NULL),
            `if`( ! missing(markers), markers, NULL))

    for (v in markers) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- multifocalconcordanceOptions$new(
        caseId = caseId,
        focusId = focusId,
        markers = markers,
        showPerMarker = showPerMarker,
        showKappa = showKappa,
        showCaseLevel = showCaseLevel,
        showDiscordance = showDiscordance,
        showPlot = showPlot,
        showSummary = showSummary,
        showExplanation = showExplanation)

    analysis <- multifocalconcordanceClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

